      await toggle.click();
      await drawer
        .getByRole("link", { name: "Back to facility", exact: true })
        .click();
      await expect(drawer).not.toBeVisible();
      await expect(page).toHaveURL(`${facilityPath}/overview`);
      await expect(settingsHeader(page)).toHaveCount(0);
    });
  });
