      await expect(
        sidebar.getByRole("link", { name: "General", exact: true }),
      ).not.toHaveAttribute("aria-current", "page");
      await page.reload();
      await expectCurrentSettingsPage(page, "Tax Codes");
      await expect(
        sidebar.getByRole("link", { name: "Tax Codes", exact: true }),
      ).toHaveAttribute("aria-current", "page");
    });

    await test.step("Templates stays in settings and Back to facility restores the workspace", async () => {
      await sidebar
        .getByRole("link", { name: "Templates", exact: true })
        .click();
      await expect(page).toHaveURL(`${facilityPath}/template`);
      await expectCurrentSettingsPage(page, "Templates");
      await expect(
        sidebar.getByRole("link", { name: "Templates", exact: true }),
      ).toHaveAttribute("aria-current", "page");
      await page.reload();
      await expectCurrentSettingsPage(page, "Templates");
      await sidebar
        .getByRole("link", { name: "Back to facility", exact: true })
        .click();
      await expect(page).toHaveURL(`${facilityPath}/overview`);
      await expect(settingsHeader(page)).toHaveCount(0);
      await expect(
        sidebar.getByRole("link", { name: "Appointments", exact: true }),
      ).toBeVisible();
      await expect(
        sidebar.getByRole("link", { name: "Settings", exact: true }),
      ).toBeVisible();
    });
  });

  test("a failed background refresh preserves an open facility editor and unsaved changes", async ({
    page,
    request,
  }) => {
    await page.goto(`${facilityPath}/settings/general`);
    const edit = page.getByRole("button", {
      name: "Edit Facility Details",
      exact: true,
    });
    await expect(edit).toBeVisible();
    const endpoint = `/api/v1${facilityPath}/`;
    let releaseFailure = () => {};
    const failureGate = new Promise<void>((resolve) => {
      releaseFailure = resolve;
    });
    await page.route(`**${endpoint}`, async (route) => {
      if (route.request().method() !== "GET") {
        await route.continue();
        return;
      }
      await failureGate;
      await route.fulfill({
        status: 503,
        contentType: "application/json",
        body: JSON.stringify({ detail: "Temporary test refresh failure" }),
      });
    });

    try {
      const failedResponse = page.waitForResponse(
        (response) =>
          new URL(response.url()).pathname === endpoint &&
          response.status() === 503,
      );
      await edit.click();
      const editor = page.getByRole("dialog", {
        name: "Edit Facility",
        exact: true,
      });
      const name = editor.getByRole("textbox", { name: "Facility Name" });
      await expect(name).toHaveValue(facilityName);
      const unsavedName = `Unsaved facility edit ${Date.now()}`;
      await name.fill(unsavedName);
      releaseFailure();
      await failedResponse;
      await expect(
        page.getByText(
          "Unable to refresh facility details. Please try again.",
          {
            exact: true,
          },
        ),
      ).toBeVisible();
      await expect(editor).toBeVisible();
      await expect(name).toHaveValue(unsavedName);
      await editor.getByRole("button", { name: "Close", exact: true }).click();
      await expect(editor).not.toBeVisible();
    } finally {
      releaseFailure();
      await page.unroute(`**${endpoint}`);
    }

    const savedFacility = await request.get(`${apiBaseUrl()}${endpoint}`, {
      headers: adminApiHeaders(),
    });
    expect(savedFacility.ok()).toBe(true);
    expect(((await savedFacility.json()) as { name: string }).name).toBe(
      facilityName,
    );
  });

  test("mobile settings navigation closes after selection and survives a deep-link reload", async ({
    page,
  }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto(`${facilityPath}/settings`);
    await expect(page).toHaveURL(`${facilityPath}/settings/general`);
    await expectCurrentSettingsPage(page, "General");
    const toggle = settingsHeader(page).getByRole("button", {
      name: "Toggle Sidebar",
      exact: true,
    });
    const drawer = page.locator('[data-sidebar="sidebar"][data-mobile="true"]');

    await test.step("the drawer selects a billing page and closes", async () => {
      await expect(drawer).not.toBeVisible();
      await toggle.click();
      await expect(drawer).toBeVisible();
      await expect(
        drawer.getByRole("link", { name: "General", exact: true }),
      ).toHaveAttribute("aria-current", "page");
      await drawer
        .getByRole("button", { name: "Billing", exact: true })
        .click();
      await drawer
        .getByRole("link", { name: "Tax Codes", exact: true })
        .click();
      await expect(drawer).not.toBeVisible();
      await expect(toggle).toHaveAttribute("aria-expanded", "false");
      await expect(page).toHaveURL(
        `${facilityPath}/settings/billing/tax_codes`,
      );
      await expectCurrentSettingsPage(page, "Tax Codes");
      await expect
        .poll(() => page.evaluate(() => document.documentElement.scrollWidth))
        .toBe(390);
    });

    await test.step("reload and selecting the current page preserve the route", async () => {
      await page.reload();
      await expectCurrentSettingsPage(page, "Tax Codes");
      await toggle.click();
      await expect(drawer).toBeVisible();
      const currentPage = drawer.getByRole("link", {
        name: "Tax Codes",
        exact: true,
      });
      await expect(currentPage).toHaveAttribute("aria-current", "page");
      await currentPage.click();
      await expect(drawer).not.toBeVisible();
      await expect(page).toHaveURL(
        `${facilityPath}/settings/billing/tax_codes`,
      );
      await toggle.click();
      await drawer
        .getByRole("link", { name: "Back to facility", exact: true })
        .click();
      await expect(drawer).not.toBeVisible();
      await expect(page).toHaveURL(`${facilityPath}/overview`);
      await expect(settingsHeader(page)).toHaveCount(0);
    });
  });
});
import { FullConfig } from "@playwright/test";
import { execFileSync } from "child_process";
import * as fs from "fs";
import * as path from "path";

// Token name constants
const ACCESS_TOKEN_KEY = "care_access_token";
const REFRESH_TOKEN_KEY = "care_refresh_token";

/**
 * Interface for localStorage items in Playwright storage state
 */
interface LocalStorageItem {
  name: string;
  value: string;
}

/**
 * Restore database from snapshot before tests run.
 * Ensures a clean, repeatable state for every test execution.
 * Skipped on CI (CI uses fresh Docker containers per run).
 */
function restoreDatabase() {
  if (process.env.CI) return;

  const snapshotFile =
    process.env.PLAYWRIGHT_DB_SNAPSHOT || "/tmp/care_playwright_snapshot.dump";
  const scriptPath = path.resolve(__dirname, "../scripts/playwright-db.sh");

  if (!fs.existsSync(snapshotFile)) {
    console.log(
      "⚠️ No DB snapshot found. Run 'npm run playwright:db-reset' to create one.",
    );
    return;
  }

  if (!fs.existsSync(scriptPath)) {
    console.log("⚠️ playwright-db.sh not found, skipping DB restore");
    return;
  }

  try {
    console.log("🔄 Restoring database from snapshot...");
    const output = execFileSync("bash", [scriptPath, "restore"], {
      stdio: "pipe",
      timeout: 30000,
      encoding: "utf-8",
    });
    if (output) console.log(output.trim());
    console.log("✅ Database restored to clean state");
  } catch (error) {
    const stderr =
      error instanceof Error && "stderr" in error
        ? (error as { stderr: string }).stderr
        : "";
    console.error(
      "⚠️ DB restore failed (tests will continue):",
      stderr || (error instanceof Error ? error.message : error),
    );
  }
}

/**
 * Refresh authentication tokens for every saved storage state using native
 * fetch. All role states (user/nurse/facilityAdmin) must be refreshed —
 * runs with `--no-deps` skip the setup project, and a stale nurse token
 * fails every permission spec while the admin ones keep passing.
 */
async function refreshTokens() {
  const authDir = path.join(__dirname, ".auth");
  if (!fs.existsSync(authDir)) {
    console.log("⚠️ Auth directory not found, skipping token refresh");
    return;
  }
  for (const file of fs.readdirSync(authDir)) {
    if (!file.endsWith(".json")) continue;
    await refreshTokensInFile(path.join(authDir, file));
  }
}

async function refreshTokensInFile(authFile: string) {
  if (!fs.existsSync(authFile)) {
    console.log("⚠️ Auth file not found, skipping token refresh");
    return;
  }

  try {
    const storageState = JSON.parse(fs.readFileSync(authFile, "utf-8"));

    if (
      !Array.isArray(storageState.origins) ||
      storageState.origins.length === 0
    ) {
      // Not a storage state (e.g. a *Meta.json id file) — nothing to refresh.
      return;
    }

    const firstOrigin = storageState.origins[0];
    const localStorage: LocalStorageItem[] = Array.isArray(
      firstOrigin.localStorage,
    )
      ? firstOrigin.localStorage
      : [];
    const accessTokenEntry = localStorage.find(
      (item: LocalStorageItem) => item.name === ACCESS_TOKEN_KEY,
    );
    const refreshTokenEntry = localStorage.find(
      (item: LocalStorageItem) => item.name === REFRESH_TOKEN_KEY,
    );

    if (!accessTokenEntry || !refreshTokenEntry) {
      console.log(`⚠️ No tokens found in ${path.basename(authFile)}`);
      return;
    }

    const refreshToken = refreshTokenEntry.value;
    const apiUrl = process.env.REACT_CARE_API_URL || "http://localhost:9000";

    console.log(`🔄 Refreshing tokens (${path.basename(authFile)})...`);

    const response = await fetch(`${apiUrl}/api/v1/auth/token/refresh/`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh: refreshToken }),
    });

    if (response.ok) {
      const data = await response.json();

      const accessIndex = localStorage.findIndex(
        (item: LocalStorageItem) => item.name === ACCESS_TOKEN_KEY,
      );
      const refreshIndex = localStorage.findIndex(
        (item: LocalStorageItem) => item.name === REFRESH_TOKEN_KEY,
      );

      if (accessIndex !== -1) {
        localStorage[accessIndex].value = data.access;
      }
      if (refreshIndex !== -1 && data.refresh) {
        localStorage[refreshIndex].value = data.refresh;
      }

      fs.writeFileSync(authFile, JSON.stringify(storageState, null, 2));

      console.log(`✅ Tokens refreshed (${path.basename(authFile)})`);
    } else {
      console.log(
        `⚠️ Token refresh failed for ${path.basename(authFile)} with status: ${response.status}`,
      );
    }
  } catch (error) {
    console.error("❌ Error refreshing tokens:", error);
  }
}

/**
 * Global setup that runs once before all tests.
 * 1. Restores database from snapshot (local only)
 * 2. Refreshes authentication tokens
 */
async function globalSetup(_config: FullConfig) {
  restoreDatabase();
  await refreshTokens();
}

export default globalSetup;
