function SidebarMenuButton({
  asChild,
  render,
  isActive = false,
  variant = "default",
  size = "default",
  tooltip,
  className,
  children,
  ...props
}: Omit<useRender.ComponentProps<"button">, "render"> & {
  asChild?: boolean;
  render?: RenderProp;
  isActive?: boolean;
  tooltip?: string | React.ComponentProps<typeof TooltipContent>;
} & VariantProps<typeof sidebarMenuButtonVariants>) {
  const resolved = resolveAsChild(asChild, children, render);
  const { isMobile, state } = useSidebar();

  const button = useRender({
    defaultTagName: "button",
    render: resolved.render,
  const pages = useRoutes(DashboardRoutes);

  const appointmentPages = useRoutes(AppointmentRoutes);

  const sidebarOpen = useSidebarState();

  if (!pages) {
    if (appointmentPages) {
      return <PatientUserProvider>{appointmentPages}</PatientUserProvider>;
    }
    return <PublicRouter />;
