import { PanelLeft } from "lucide-react";
import { ComponentProps } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { useSidebar } from "@/components/ui/sidebar";
import { TooltipComponent } from "@/components/ui/tooltip";

export function AppSidebarToggle({
  className,
  onClick,
  ...props
}: ComponentProps<typeof Button>) {
  const { t } = useTranslation();
  const { isMobile, openMobile, open, toggleSidebar } = useSidebar();

  return (
    <TooltipComponent content={t("toggle_sidebar")} side="right">
      <Button
        type="button"
        variant="ghost"
        size="icon"
        data-sidebar="trigger"
        aria-label={t("toggle_sidebar")}
        aria-expanded={isMobile ? openMobile : open}
        className={cn(
          "size-8 text-neutral-600 hover:bg-neutral-200 hover:text-neutral-950 focus-visible:ring-2 focus-visible:ring-indigo-400",
          className,
        )}
        onClick={(event) => {
          onClick?.(event);
          if (!event.defaultPrevented) toggleSidebar();
        }}
        {...props}
      >
        <PanelLeft className="size-4" aria-hidden="true" />
      </Button>
    </TooltipComponent>
  );
}
