import { usePath } from "raviger";
import { useTranslation } from "react-i18next";

import { InnerPageHeader } from "@/components/Common/InnerPageHeader";

import useCurrentLocation from "@/pages/Facility/locations/utils/useCurrentLocation";

export function LocationPageHeader() {
  const { t } = useTranslation();
  const { facilityId, locationId, location } = useCurrentLocation();
  const path = usePath() ?? "";
  const baseUrl = `/facility/${facilityId}/locations/${locationId}`;
  const section = path.slice(baseUrl.length);
  const pageTitles = [
    ["/responses", t("responses")],
    ["/forms", t("responses")],
    ["/beds", t("beds")],
    ["/service_requests", t("service_requests")],
    ["/medication_requests", t("prescription_queue")],
    ["/medication_dispense", t("dispense")],
    ["/medication_return", t("medication_return")],
    ["/inventory/internal/receive", t("to_receive")],
    ["/inventory/internal/dispatch", t("to_dispatch")],
    ["/inventory/external/orders", t("purchase_orders")],
    ["/inventory/external/deliveries", t("purchase_deliveries")],
    ["/inventory", t("inventory")],
    ["/schedule", t("schedule")],
    ["/appointments", t("appointments")],
    ["/queues", t("queues")],
  ];
  const pageTitle =
    pageTitles.find(([prefix]) => section.startsWith(prefix))?.[1] ??
    t("overview");

  return (
    <InnerPageHeader
      dataCy="location-page-header"
      breadcrumbs={[
        { label: location?.name ?? t("location"), href: `${baseUrl}/overview` },
        { label: pageTitle },
      ]}
    />
  );
}
import { usePath } from "raviger";
import { useTranslation } from "react-i18next";

import { getFacilitySettingsPageTitle } from "@/components/ui/sidebar/facility/settings/facility-settings-nav";

import { InnerPageHeader } from "@/components/Common/InnerPageHeader";

import { DevicePageHeader } from "@/pages/Facility/settings/devices/DevicePageHeader";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";

export function FacilitySettingsPageHeader() {
  const { t } = useTranslation();
  const { facilityId, facility } = useCurrentFacility();
  const path = usePath() ?? "";
  const baseUrl = `/facility/${facilityId}`;
  const deviceId = path.match(
    /^\/facility\/[^/]+\/settings\/devices\/([^/]+)(?:\/responses)?\/?$/,
  )?.[1];

  if (deviceId && deviceId !== "create") {
    return (
      <DevicePageHeader
        facilityId={facilityId}
        facilityName={facility?.name ?? t("facility")}
        deviceId={deviceId}
      />
    );
  }

  return (
    <InnerPageHeader
      dataCy="facility-settings-page-header"
      breadcrumbs={[
        {
          label: facility?.name ?? t("facility"),
          href: `${baseUrl}/overview`,
          hideOnMobile: true,
        },
        { label: t("settings"), href: `${baseUrl}/settings/general` },
        { label: getFacilitySettingsPageTitle(path, t) },
      ]}
    />
  );
}
import { useMemo } from "react";

export default function useSidebarState() {
  return useMemo(() => {
    const cookie = document.cookie
      .split("; ")
      .find((row) => row.startsWith("sidebar:state"));

    if (cookie) {
      const value = cookie.split("=")[1];
      return value === "true";
    }

    return false;
  }, []);
}
import { ChevronsUpDown, LayoutDashboard, ShieldCheck } from "lucide-react";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/components/ui/sidebar";
import { NavMain } from "@/components/ui/sidebar/nav-main";

import { useAccessibleRoleOrganizationsList } from "@/hooks/useAccessibleRoleOrganizationsList";

interface Props {
  selectedResponsibilityId: string;
}

export function ResponsibilitySwitcher({ selectedResponsibilityId }: Props) {
  const { state, isMobile, setOpenMobile } = useSidebar();
  const isCollapsed = state === "collapsed" && !isMobile;
  const { t } = useTranslation();

  const { data } = useAccessibleRoleOrganizationsList();

  const items = data?.results || [];
  const selectedItem = items.find(
    (item) => item.organization.id === selectedResponsibilityId,
  );

  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <SidebarMenuButton
              size="lg"
              className="h-auto rounded-[10px] border border-neutral-300 bg-white px-3 py-2.5 text-neutral-950 hover:bg-neutral-100 hover:text-neutral-950 focus-visible:ring-indigo-400 data-[state=open]:bg-neutral-100 data-[state=open]:text-neutral-950"
              tooltip={t("responsibilities")}
              aria-label={
                selectedItem?.organization.name || t("responsibilities")
              }
            >
              <div className="flex aspect-square size-8 shrink-0 items-center justify-center rounded-lg bg-neutral-100 text-neutral-600">
                <ShieldCheck className="size-4" />
              </div>
              {!isCollapsed && (
                <>
                  <div className="grid min-w-0 flex-1 gap-0.5 text-left text-sm leading-tight">
                    <span className="truncate font-semibold">
                      {selectedItem?.organization.name || t("responsibilities")}
                    </span>
                    {selectedItem?.role && (
                      <span className="truncate text-xs text-neutral-600">
                        {selectedItem.role.name}
                      </span>
                    )}
                  </div>
                  <ChevronsUpDown className="ml-auto size-4 text-neutral-600" />
                </>
              )}
            </SidebarMenuButton>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            className="w-(--radix-dropdown-menu-trigger-width) min-w-56 rounded-lg max-h-screen overflow-y-auto"
            align="start"
            side={isMobile ? "bottom" : "right"}
            sideOffset={4}
          >
            <DropdownMenuItem asChild>
              <Link
                className="flex items-center gap-2 cursor-pointer"
                href="/"
                onClick={() => isMobile && setOpenMobile(false)}
              >
                <LayoutDashboard className="size-4" />
                {t("view_dashboard")}
              </Link>
            </DropdownMenuItem>
            <DropdownMenuLabel>{t("responsibilities")}</DropdownMenuLabel>
            <DropdownMenuSeparator />
            {items.map((item) => (
              <DropdownMenuItem
                key={item.organization.id}
                asChild
                className={cn(
                  "gap-2 p-2",
                  item.organization.id === selectedResponsibilityId &&
                    "bg-neutral-100 font-medium text-neutral-950 focus:bg-neutral-200 focus:text-neutral-950",
                )}
              >
                <Link
                  href={`/responsibilities/${item.organization.id}`}
                  aria-current={
                    item.organization.id === selectedResponsibilityId
                      ? "true"
                      : undefined
                  }
                  onClick={() => isMobile && setOpenMobile(false)}
                >
                  <div className="flex flex-col">
                    <span>{item.organization.name}</span>
                    {item.role && (
                      <span className="text-xs opacity-70">
                        {item.role.name}
                      </span>
                    )}
                  </div>
                </Link>
              </DropdownMenuItem>

