    if (!isOverlay) return;
    const handleEscape = (event: KeyboardEvent) => {
      if (
        event.key !== "Escape" ||
        event.defaultPrevented ||
        menuOpen.current
      ) {
        return;
      }
      event.preventDefault();
      closeOverlay();
    };
