                    </span>{" "}
                    👋
                  </h1>
                  <p className="text-muted-foreground text-sm">Welcome back!</p>
                </div>
              </div>
              <Tabs defaultValue="overview">
                <TabsList
                  variant="line"
                  className="border-border w-full border-b"
