                              {link.description}
                            </CardDescription>
                          )}
                          <CardTitle className="text-xl font-semibold text-gray-900">
                            {link.title}
                          </CardTitle>
                        </div>
                        <ArrowUpRight className="size-5 text-gray-400 shrink-0" />
                      </CardContent>
                    </Card>
                  </Link>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </Page>
  );
}
